import{z as i,x as n,o as B,c as s,q as e,j as r,D as a,d as t,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"抢占与请求迁移","description":"","frontmatter":{"title":"抢占与请求迁移","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-preemption-migration.md","filePath":"llm/sch-preemption-migration.md","lastUpdated":1791063341000}'),m={name:"llm/sch-preemption-migration.md"};function C(p,E,D,d,h,_){const A=n("Mermaid");return B(),s("div",null,[E[2]||(E[2]=e('<h1 id="抢占与请求迁移" tabindex="-1">抢占与请求迁移 <a class="header-anchor" href="#抢占与请求迁移" aria-label="Permalink to &quot;抢占与请求迁移&quot;">​</a></h1><div class="epigraph"><p>抢占的题目不是「能不能让路」，而是「让路的钱从哪本账出」：重算花算力，换出花带宽，迁移花网络——三条路各有定价。</p><footer>—— 据 Kwon et al., SOSP 2023 的换出与重算口径，按站内 KV 成本核算整理</footer></div><p><a href="/llm/sch-slo-tiers">上一课</a>把承诺分层；合同要有强制执行的手段，那个手段就是抢占：当 KV 池或预算见底时，谁让路、怎么让、代价几何。vLLM 调度器的抢占循环与「长前缀倾向换出、短请求倾向重算」的启发式主干已有（<a href="/llm/vllm-scheduler">vLLM 调度器</a>、<a href="/llm/preemption-fairness">抢占与公平性</a>）；本课把三条让路——重算、换出、迁移——写成一本代价账，并补上迁移这个未展开的选项：它把「让路」从损失变成搬运，是排干与伸缩的前置件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>抢占触发于 decode 中途：池子见水，本步写不下新 KV。三条路的代价结构完全不同。<strong>重算</strong>丢弃 KV，回来时重做前缀 prefill：代价是算力，正比于前缀长度。<strong>换出</strong>把 KV 搬到主机再搬回来：代价是两次主机间搬运，正比于 KV 字节。<strong>迁移</strong>把 KV 与块表搬到另一实例：代价是网络搬运加目标端对齐。选错路的浪费是实打实的：短前缀的请求做了昂贵的换出，长前缀的请求重算了半分钟的前填。更糟的是抖动：水位无滞回时，换出回来立刻再换出，GPU 在搬字节不产 token——抢占风暴比抢占本身更伤。</p><h3 id="代价模型与受害者选择" tabindex="-1">代价模型与受害者选择 <a class="header-anchor" href="#代价模型与受害者选择" aria-label="Permalink to &quot;代价模型与受害者选择&quot;">​</a></h3><p>决策按账本走：重算代价 \\(t_{\\mathrm{re}}\\approx L_{\\mathrm{prefix}}/r_{\\mathrm{prefill}}\\)；换出代价 \\(t_{\\mathrm{swap}}\\approx 2B_{\\mathrm{KV}}/b_{\\mathrm{PCIe}}\\)（下行加回迁）；迁移代价 \\(t_{\\mathrm{mig}}\\approx B_{\\mathrm{KV}}/b_{\\mathrm{net}}\\) 加对齐成本。三者谁便宜取决于前缀长度、KV 头数与链路带宽，没有普适答案，系数按部署实测。受害者选择按「优先级优先、同级看释放效率」：低级类先让；同级让「单位等待释放字节最多」的——通常是 KV 占用大、已完成生成短的请求。触发用水位加滞回：越过高水位线才抢占，回落到低水位线才恢复准入，中间是恢复区。<span class="marginnote">术语翻译：滞回就是「开与关用两条不同的线」——空调制冷到 24 度才停、升到 26 度才重新开，而不是卡在 25 度反复启停。抢占里两条线之间的地带叫恢复区，专门用来防止「刚换出又立刻换出」的抖动。</span></p>',7)),(B(),r(o,null,{default:a(()=>[l(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20WM%7B%22%E6%B0%B4%E4%BD%8D%E8%B6%8A%E8%BF%87%E9%AB%98%E5%8E%8B%E7%BA%BF%22%7D%20--%3E%20VICT%5B%22%E9%80%89%E5%8F%97%E5%AE%B3%E8%80%85%EF%BC%9A%E4%BC%98%E5%85%88%E7%BA%A7%EF%BC%8C%E5%86%8D%E9%87%8A%E6%94%BE%E6%95%88%E7%8E%87%22%5D%0A%20%20VICT%20--%3E%20COST%7B%22%E4%B8%89%E6%9C%AC%E8%B4%A6%E8%B0%81%E6%9C%80%E4%BE%BF%E5%AE%9C%22%7D%0A%20%20COST%20--%3E%7C%E5%89%8D%E7%BC%80%E7%9F%AD%7C%20RE%5B%22%E9%87%8D%E7%AE%97%EF%BC%9A%E4%B8%A2%20KV%EF%BC%8C%E5%9B%9E%E6%9D%A5%E9%87%8D%20prefill%22%5D%0A%20%20COST%20--%3E%7C%E5%89%8D%E7%BC%80%E9%95%BF%7C%20SW%5B%22%E6%8D%A2%E5%87%BA%EF%BC%9AKV%20%E4%B8%8B%E8%A1%8C%EF%BC%8C%E5%9B%9E%E6%9D%A5%E4%B8%8A%E8%A1%8C%22%5D%0A%20%20COST%20--%3E%7C%E6%9C%89%E5%AF%B9%E7%AD%89%E5%AE%9E%E4%BE%8B%7C%20MG%5B%22%E8%BF%81%E7%A7%BB%EF%BC%9AKV%20%E4%B8%8E%E5%9D%97%E8%A1%A8%E8%BF%87%E7%BD%91%22%5D%0A%20%20RE%20--%3E%20BACK%5B%22%E5%9B%9E%E9%98%9F%E7%AD%89%E5%BE%85%E5%86%8D%E5%85%A5%22%5D%0A%20%20SW%20--%3E%20BACK%0A%20%20MG%20--%3E%20JOIN%5B%22%E5%9C%A8%E7%9B%AE%E6%A0%87%E5%AE%9E%E4%BE%8B%E7%BB%AD%E8%B7%91%22%5D%0A%20%20BACK%20--%3E%20LOW%7B%22%E6%B0%B4%E4%BD%8D%E5%9B%9E%E8%90%BD%E5%88%B0%E4%BD%8E%E5%8E%8B%E7%BA%BF%22%7D%0A%20%20LOW%20--%3E%7C%E6%98%AF%7C%20RESUME%5B%22%E6%81%A2%E5%A4%8D%E5%87%86%E5%85%A5%22%5D%0A%20%20LOW%20--%3E%7C%E5%90%A6%7C%20WM%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>把决策写成代价账本</strong>：三条让路各配一条显式代价式——重算正比前缀长、换出正比 KV 字节、迁移正比网络字节加对齐——选路退化为三本账比价，系数按部署实测填，公式只钉方向。<span class="marginnote">直觉类比：迁移像搬家时把家具原样运到新家，进门就能接着住；重算像把家具扔掉，到新家照着照片重新打一套。家越「大」（前缀越长、KV 越多），重打一遍就越贵——所以长前缀倾向搬（换出或迁移），短前缀干脆扔了重来。</span>策略件只有两枚：受害者按「优先级优先、同级看释放效率」排序，触发用水位加滞回防抖。方法上的钉子：抢占不是单一动作，而是一个参数化决策，账本让「选错路」从事故变成可审的错误。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>抢占率本身是健康指标：常态非零说明水位定错或容量不足，持续攀升是过载的前兆，运维单元展开。<span class="marginnote">常见误区：初学者容易以为抢占率越低越好、设成恒零最好。常态抢占率恒为零，往往说明水位留得太宽、卡在空转；健康的系统抢占率非零但小且平稳。它「持续非零或一路飙升」才是水位定错或容量不足的信号——看趋势，不看单点。</span>它同时是策略的执行器：上一课的层在迭代边界如何「真的」优先？答案就是抢占序——高压线触发时按层从低到高请出，合同分级在此获得牙齿。迁移的机制约束在接收端：目标实例必须能接管块表与适配器、并行度兼容、版本兼容；decode 的每一步都要读家（<a href="/llm/decode-affinity">Decode 实例的亲和与缓存</a>），搬家要连家一起搬。KV 课程已给过迁移的兜底定价原则——先路由后搬运，重算永远兜底（<a href="/llm/kv-map">KV 管理收束</a>）；本课把它落到三条路的实测系数上。</p><p>滞回防抖的完整回路：</p>',5)),(B(),r(o,null,{default:a(()=>[l(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20RISE%5B%22KV%20%E6%B1%A0%E6%B0%B4%E4%BD%8D%E4%B8%8A%E6%B6%A8%22%5D%20--%3E%20H%7B%22%E8%B6%8A%E8%BF%87%E9%AB%98%E5%8E%8B%E7%BA%BF%EF%BC%9F%22%7D%0A%20%20H%20--%3E%7C%22%E5%90%A6%22%7C%20OK%5B%22%E6%AD%A3%E5%B8%B8%E8%BF%90%E8%A1%8C%22%5D%0A%20%20H%20--%3E%7C%22%E6%98%AF%22%7C%20PRE%5B%22%E8%A7%A6%E5%8F%91%E6%8A%A2%E5%8D%A0%EF%BC%9A%E6%8C%89%E5%B1%82%E8%AF%B7%E5%87%BA%E5%8F%97%E5%AE%B3%E8%80%85%22%5D%0A%20%20PRE%20--%3E%20FALL%5B%22%E8%AE%A9%E8%B7%AF%E5%90%8E%E6%B0%B4%E4%BD%8D%E5%9B%9E%E8%90%BD%22%5D%0A%20%20FALL%20--%3E%20L%7B%22%E8%B7%8C%E7%A0%B4%E4%BD%8E%E5%8E%8B%E7%BA%BF%EF%BC%9F%22%7D%0A%20%20L%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E4%BB%8D%E5%9C%A8%E6%81%A2%E5%A4%8D%E5%8C%BA%22%7C%20HOLD%5B%22%E4%B8%8D%E6%81%A2%E5%A4%8D%E5%87%86%E5%85%A5%EF%BC%8C%E4%B9%9F%E4%B8%8D%E5%86%8D%E8%BF%BD%E5%8A%A0%E6%8A%A2%E5%8D%A0%22%5D%0A%20%20L%20--%3E%7C%22%E6%98%AF%22%7C%20RES%5B%22%E6%81%A2%E5%A4%8D%E5%87%86%E5%85%A5%EF%BC%8C%E5%9B%9E%E5%88%B0%E6%AD%A3%E5%B8%B8%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">一条量级账：4k token、GQA 8 KV 头、128 维、32 层、fp16 的序列，KV 约 0.5 GB。PCIe 4.0 有效带宽按 20–30 GB/s 算，换出加回迁约 40–60 ms；同一前缀重算按单卡数千 token/s 的 prefill 是秒级。系数随硬件代际与精度变，方向（长前缀换出、短前缀重算）目前稳定。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>迁移不是免费容错：跨异构、跨并行度、跨版本通常只能退化为重算；它解决的是计划内的排干（升级、缩容），不是硬件故障的恢复——故障走重路由加重算。换出与重算在流式上都表现为 TBT 空洞，用户可感知，合同要为「被抢占类」预留更松的 TPOT 分位，而不是假装抢占不存在。抢占也受批语义限制：束搜索与并行采样的 fork 组要同进同出，拆散一组省下的块可能不够付对齐的复杂度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三条让路各有账本：重算花算力（正比前缀长）、换出花带宽（正比 KV 字节）、迁移花网络加对齐。</li><li>受害者按优先级优先、同级按释放效率；水位加滞回防抖。</li><li>抢占率是健康指标；常态非零是水位或容量错了。</li><li>迁移让排干可行：升级与缩容不丢在途请求，是弹性伸缩的前置件。</li><li>被抢占类的合同要预留更松的 TPOT 分位。</li><li>出处：Kwon et al., SOSP 2023（换出与重算的原文口径）；迁移代价按站内 KV 课程的核算口径整理。</li></ul>',5))])}const f=i(m,[["render",C]]);export{c as __pageData,f as default};
